import time
import torch
import torch.nn as nn

model = nn.Sequential(nn.Linear(512, 1024), nn.GELU(), nn.Linear(1024, 256)).eval()
inputs = torch.randn(64, 512)
compiled_model = torch.compile(model)

@torch.inference_mode()
def benchmark(fn, warmup=10, iterations=50):
    for _ in range(warmup):
        fn()
    if inputs.is_cuda:
        torch.cuda.synchronize()
    start = time.perf_counter()
    for _ in range(iterations):
        fn()
    if inputs.is_cuda:
        torch.cuda.synchronize()
    return (time.perf_counter() - start) / iterations

# The example uses CPU tensors. Move both models and inputs to CUDA to benchmark a GPU workload.
eager_time = benchmark(lambda: model(inputs))
compiled_time = benchmark(lambda: compiled_model(inputs))
print({"eager_seconds": eager_time, "compiled_seconds": compiled_time, "speedup": eager_time / compiled_time})
